<style id="appifact-style">
/**
 * Omelette design tokens as CSS custom properties.
 *
 * Single source of truth for the app's palette, shadows, and z-layers.
 * Values mirror `components/colors.ts` and `components/zLayers.ts` exactly;
 * `colors.test.ts` enforces the match. Tailwind utilities
 * (`text-om-text-primary`, `bg-om-bg-app`, `shadow-om-sm`, `z-om-modal`, …)
 * resolve to these vars via `tailwind.config.cjs`.
 *
 * The `om-` prefix keeps every utility distinct from CDS's own vocabulary
 * (`text-primary`, `shadow-sm`, …), which must keep resolving to `--cds-*`
 * for the CDS components already in use.
 *
 * `colors.ts` remains the typed JS mirror for inline `style={{…}}` callers
 * and must stay in sync with this file.
 */

:root {
  /* Tells the UA which palette native controls (scrollbars, form widgets,
   * the overscroll gutter) should use. Without this a dark-mode page still
   * gets light scrollbars and a white rubber-band background on macOS/iOS. */
  color-scheme: light;

  /* bg */
  --om-bg-app: #faf9f5;
  --om-bg-panel: #f8f7f3;
  --om-bg-surface: #ffffff;
  --om-bg-elevated: #ffffff;
  --om-bg-hover: rgba(15, 12, 8, 0.04);
  /* --om-bg-hover flattened over surface, for elements floating over
   * arbitrary content. Keep ink/alpha in sync with --om-bg-hover. */
  --om-bg-hover-opaque: color-mix(
    in srgb,
    rgb(15, 12, 8) 4%,
    var(--om-bg-surface)
  );
  --om-bg-active: #e8e6dc;
  --om-bg-selected: #e3dacc;
  --om-bg-muted: #f0eee6;
  --om-bg-stripe: rgba(15, 12, 8, 0.02);
  --om-bg-tint-design-system: #f6e3e3;
  --om-bg-tint-template: #e4e2f1;
  --om-bg-primary-tab-bar: #e8e6dc;
  --om-bg-secondary-tab-bar: #f6f5f0af;
  --om-bg-error-tint: rgba(166, 50, 68, 0.05);
  --om-bg-intro-splash: #e1dacd;
  /* Sliding-thumb fill for segmented controls (DcPropsPanel). White in
   * light — bg-selected there reads as a second tint, not a thumb — and
   * the selected tone in dark, where white would glare. */
  --om-bg-thumb: #ffffff;
  /* Modal/popover backdrop. Darker in dark mode so the panel still
   * separates from the page; a fixed dark scrim on a dark page reads
   * as no scrim at all. */
  --om-bg-scrim: rgba(15, 12, 8, 0.4);

  /* border */
  --om-border-subtle: rgba(15, 12, 8, 0.08);
  --om-border-card: rgba(15, 12, 8, 0.12);
  --om-border-default: rgba(15, 12, 8, 0.1);
  --om-border-strong: rgba(15, 12, 8, 0.22);
  --om-border-focus: rgba(15, 12, 8, 0.36);
  --om-border-modal: rgba(0, 0, 0, 0.1);

  /* text */
  --om-text-primary: rgba(15, 12, 8, 0.92);
  --om-text-prose: rgba(15, 12, 8, 0.8);
  --om-text-secondary: rgba(15, 12, 8, 0.64);
  --om-text-tertiary: rgba(15, 12, 8, 0.6);
  --om-text-disabled: rgba(15, 12, 8, 0.32);
  --om-text-design-system-badge: #c67878;
  --om-text-inverse: #faf9f5;
  --om-text-link: #6a9bcc;

  /* accent */
  --om-accent-primary: #d97757;
  --om-accent-primary-bg: rgba(217, 119, 87, 0.12);
  --om-accent-primary-tint: rgba(217, 119, 87, 0.04);
  --om-accent-primary-hover: #c46a4d;
  --om-accent-primary-active: #b05e43;
  --om-accent-secondary: #6a9bcc;
  --om-accent-secondary-hover: #5a8bbb;
  --om-accent-secondary-active: #4e7caa;
  --om-accent-success: #558a42;
  /* Muted sage for the todo checklist's done-state — softer than the
   * status green so a long completed list doesn't read as a wall of
   * success badges. Non-text fill: ≥3:1 against bg.surface in dark. */
  --om-accent-sage: #788c5d;
  --om-accent-warning: #c9a82d;
  --om-accent-error: #a63244;
  /* Destructive button hover/active. Light deepens toward black (the
   * resolved values of the former color-mix toward black); dark lightens
   * toward white instead — mixing toward black on an already-light dark
   * accent inverts the affordance and drops text contrast. All states
   * keep ≥4.5:1 against text-inverse. */
  --om-accent-error-hover: #992e3f;
  --om-accent-error-active: #8d2b3a;
  --om-accent-pro: #473aa6;
  --om-accent-pro-bg: #e7e4fb;
  --om-accent-blue: #2a78d6;
  --om-accent-blue-bg: rgba(42, 120, 214, 0.1);
  --om-accent-blue-hover: #2569bf;
  --om-accent-review: #3987e5;
  --om-accent-verifier: #8b6ac8;
  --om-accent-verifier-soft: #b7a3dc;
  /* Component artboards on the design canvas (imported by another file):
   * frame ring + title ink. */
  --om-accent-component: #8b6ac8;
  --om-accent-component-text: #473aa6;
  --om-accent-black: #191915;
  --om-accent-black-hover: #2b2b26;
  --om-accent-black-active: #0f0c08;

  /* scrollbar */
  --om-scrollbar-thumb: rgba(0, 0, 0, 0.15);
  --om-scrollbar-thumb-hover: rgba(0, 0, 0, 0.25);

  /* shadow */
  --om-shadow-xs: 0 1px 2px rgba(20, 20, 19, 0.04);
  --om-shadow-sm: 0 1px 3px rgba(20, 20, 19, 0.06);
  --om-shadow-md: 0 4px 6px rgba(20, 20, 19, 0.06);
  --om-shadow-diffuse: 0 4px 20px rgba(20, 20, 19, 0.04);
  --om-shadow-lg: 0 10px 15px rgba(20, 20, 19, 0.08);
  --om-shadow-inset: inset 0 1px 2px rgba(20, 20, 19, 0.06);
  --om-shadow-modal:
    0 24px 48px rgba(15, 12, 8, 0.16), 0 8px 16px rgba(15, 12, 8, 0.08);
  --om-shadow-card:
    0 18px 44px rgba(20, 20, 19, 0.1), 0 3px 10px rgba(20, 20, 19, 0.05);
  --om-shadow-pin: 0 2px 6px rgba(0, 0, 0, 0.25);
  --om-shadow-pin-hover: 0 3px 10px rgba(0, 0, 0, 0.3);
  /* Segmented-control thumb lift. Light keeps the soft classic 0.12; dark
   * needs a heavier alpha for the lift to read at all. */
  --om-shadow-thumb: 0 1px 2px rgba(0, 0, 0, 0.12);

  /* presenter (standalone dark window) */
  --om-presenter-bg: #1a1a1a;
  --om-presenter-text: #e8e8e8;
  --om-presenter-border: #333333;
  --om-presenter-divider: #2a2a2a;
  --om-presenter-divider-hover: #3a3a3a;
  --om-presenter-slide-bg: #000000;
  --om-presenter-slide-hover-border: #555555;
  --om-presenter-control-bg: #2a2a2a;
  --om-presenter-control-hover: #333333;
  --om-presenter-control-active: #3a3a3a;
  --om-presenter-control-border: #444444;
  --om-presenter-muted: #999999;
  --om-presenter-label: #888888;
  --om-presenter-placeholder: #555555;
  --om-presenter-toggle-track: #3a3a3a;

  /* z-layers */
  --om-z-modal: 2000;
  --om-z-modal-top: 3000;
  --om-z-popover: 3500;
  --om-z-panel-overlay: 4000;
  --om-z-toast: 10000;
}

/**
 * Dark theme. Warm-neutral (not blue-gray) — same hue family as the light
 * palette, inverted. Text/border use the light bg.app hex (#FAF9F5) as the
 * alpha base so the warmth carries through. presenter.* and z-* are
 * mode-independent and not overridden here.
 *
 * Applied via `data-theme="dark"` on <html> — stamped pre-paint by the
 * FOUC guard at the top of the app bundle (build.ts banner) and kept in
 * sync by hooks/useTheme.ts.
 */
:root[data-theme='dark'] {
  color-scheme: dark;

  /* bg */
  --om-bg-app: #1c1b19;
  --om-bg-panel: #222220;
  --om-bg-surface: #2a2927;
  --om-bg-elevated: #2a2927;
  --om-bg-hover: rgba(250, 249, 245, 0.13);
  /* See the light-theme note: hover wash flattened over surface. */
  --om-bg-hover-opaque: color-mix(
    in srgb,
    rgb(250, 249, 245) 13%,
    var(--om-bg-surface)
  );
  --om-bg-active: #35332c;
  --om-bg-selected: #3c392f;
  --om-bg-muted: #2e2c26;
  --om-bg-stripe: rgba(250, 249, 245, 0.02);
  --om-bg-tint-design-system: #3a2a2a;
  --om-bg-tint-template: #2a2838;
  --om-bg-primary-tab-bar: #35332c;
  --om-bg-secondary-tab-bar: #222220af;
  --om-bg-error-tint: rgba(196, 90, 106, 0.12);
  --om-bg-intro-splash: #2e2a22;
  --om-bg-thumb: #3c392f;
  --om-bg-scrim: rgba(0, 0, 0, 0.6);

  /* border */
  --om-border-subtle: rgba(250, 249, 245, 0.1);
  --om-border-card: rgba(250, 249, 245, 0.14);
  --om-border-default: rgba(250, 249, 245, 0.12);
  --om-border-strong: rgba(250, 249, 245, 0.24);
  --om-border-focus: rgba(250, 249, 245, 0.4);
  --om-border-modal: rgba(250, 249, 245, 0.12);

  /* text */
  --om-text-primary: rgba(250, 249, 245, 0.92);
  --om-text-prose: rgba(250, 249, 245, 0.8);
  --om-text-secondary: rgba(250, 249, 245, 0.64);
  --om-text-tertiary: rgba(250, 249, 245, 0.6);
  --om-text-disabled: rgba(250, 249, 245, 0.32);
  --om-text-design-system-badge: #d89a9a;
  --om-text-inverse: #1c1b19;
  --om-text-link: #7eaeda;

  /* accent */
  --om-accent-primary: #e08968;
  --om-accent-primary-bg: rgba(224, 137, 104, 0.16);
  --om-accent-primary-tint: rgba(224, 137, 104, 0.06);
  --om-accent-primary-hover: #e89b7e;
  --om-accent-primary-active: #efad94;
  --om-accent-secondary: #7eaeda;
  --om-accent-secondary-hover: #91bce2;
  --om-accent-secondary-active: #a4c9e9;
  --om-accent-success: #6fa859;
  --om-accent-sage: #8fae6a;
  --om-accent-warning: #dabe4a;
  /* ≥4.5:1 on bg.surface (#2a2927) and on the error-tint composite
   * (#3c2f2f) so error text stays AA on every dark error surface. */
  --om-accent-error: #dc8290;
  --om-accent-error-hover: #df8c99;
  --om-accent-error-active: #e195a1;
  --om-accent-pro: #9a8fe0;
  --om-accent-pro-bg: #2c2847;
  --om-accent-blue: #4d90e0;
  --om-accent-blue-bg: rgba(77, 144, 224, 0.14);
  --om-accent-blue-hover: #62a0e8;
  --om-accent-review: #5a9bec;
  --om-accent-verifier: #a68dd8;
  --om-accent-verifier-soft: #8572b0;
  --om-accent-component: #a68dd8;
  --om-accent-component-text: #b9aaf0;
  --om-accent-black: #f0eee6;
  --om-accent-black-hover: #e4e2d9;
  --om-accent-black-active: #d8d5cb;

  /* scrollbar */
  --om-scrollbar-thumb: rgba(250, 249, 245, 0.15);
  --om-scrollbar-thumb-hover: rgba(250, 249, 245, 0.25);

  /* shadow — same structure, higher-alpha black so depth still reads on dark surfaces */
  --om-shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.24);
  --om-shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.28);
  --om-shadow-md: 0 4px 6px rgba(0, 0, 0, 0.28);
  --om-shadow-diffuse: 0 4px 20px rgba(0, 0, 0, 0.24);
  --om-shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.32);
  --om-shadow-inset: inset 0 1px 2px rgba(0, 0, 0, 0.28);
  --om-shadow-modal:
